SELECT * FROM (
    SELECT t.*, ROW_NUMBER() OVER (ORDER BY t.create_time DESC) AS rn
    FROM thjs.tb_proj_flow_inst t
    WHERE t.flow_code = #{flowCode}
      AND t.send_status = #{sendStatus}
      AND (t.lock_flag = '0' OR t.lock_flag IS NULL)
) WHERE rn <= #{page.size}
  AND rn > (#{page.current} - 1) * #{page.size}

